      kind.hashCode ^
      issuer.hashCode ^
      account.hashCode ^
      algorithm.hashCode ^
      digits.hashCode ^
      period.hashCode ^
      counter.hashCode ^
      duplicateOf.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is EntryPreview &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          issuer == other.issuer &&
          account == other.account &&
          algorithm == other.algorithm &&
          digits == other.digits &&
          period == other.period &&
          counter == other.counter &&
          duplicateOf == other.duplicateOf;
